// Generated by AI, edited by humans
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { build } from 'vite';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const SRC_DIR = path.join(__dirname, 'src');

function findHtmlPages() {
    const pages = [];

    function scan(dir) {
        for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
            const fullPath = path.join(dir, entry.name);
            if (entry.isDirectory()) {
                scan(fullPath);
            } else if (entry.isFile() && entry.name.endsWith('.html')) {
                const relPath = path.relative(__dirname, fullPath);
                pages.push(relPath);
            }
        }
    }

    scan(SRC_DIR);

    return pages.sort((a, b) => {
        const aIsRoot = a === path.join('src', 'index.html');
        const bIsRoot = b === path.join('src', 'index.html');
        if (aIsRoot) return -1;
        if (bIsRoot) return 1;
        return a.localeCompare(b);
    });
}

export async function buildPages({ emptyOutDir = true } = {}) {
    const htmlPages = findHtmlPages();

    for (let i = 0; i < htmlPages.length; i++) {
        await build({
            build: {
                emptyOutDir: i === 0 ? emptyOutDir : false,
                rollupOptions: {
                    input: htmlPages[i],
                },
            },
        });
    }
}

if (process.argv[1] && import.meta.url.endsWith(process.argv[1].replace(/\\/g, '/'))) {
    const emptyOutDir = process.argv.includes('--emptyOutDir');
    await buildPages({ emptyOutDir });
}
